#!/usr/bin/env bash
# GENERATED by plugin-cursor/scripts/compose.sh — edit core/ or plugin-claude/ then re-compose
# Copyright (c) 2024-2026 H3Tech Inc. All rights reserved. PROPRIETARY.
#
# Hook: SessionStart
# Purpose: Warm the CLI skill cache so agents can resolve SKILL.md bodies offline.
#
# The control-plane URL is stamped at build time into hooks/lib/cp-url
# (or gitignored hooks/lib/cp-url.local after `./synaptory deploy local`).
# SYNAPTORY_CONTROL_PLANE_URL / SYNAPTORY_CP_ENV are ignored.

set -euo pipefail

PLUGIN_ROOT="${PLUGIN_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}"
# shellcheck source=./_plugin-env.sh
source "${PLUGIN_ROOT}/hooks/_plugin-env.sh"
# shellcheck source=./_cp-url.sh
source "${PLUGIN_ROOT}/hooks/_cp-url.sh"

if [[ -z "$_cp_url" ]] || [[ "$_cp_url" == "SYNAPTORY_CP_URL_PLACEHOLDER" ]]; then
  echo "synaptory: control-plane URL not stamped in this build; cannot fetch skills." >&2
  echo "  Run ./synaptory deploy local or install a marketplace build." >&2
  exit 1
fi

# shellcheck source=lib/resolve-python.sh
source "${PLUGIN_ROOT}/hooks/lib/resolve-python.sh"
_py="${SYNAPTORY_PYTHON:-python3}"

cli=$("${PLUGIN_ROOT}/hooks/_resolve-cli.sh" 2>/dev/null || true)
if [[ -z "$cli" ]] || [[ ! -x "$cli" ]]; then
  echo "synaptory: CLI binary not found; cannot fetch skills." >&2
  exit 1
fi

# Best-effort cache warm. Dist packages have no on-disk protocol fallback
# (ADR-016), so materialization below is fail-closed. reloadSkills fires
# only after the required set is on disk — never before.
"$cli" skills sync >/dev/null 2>&1 || true

if [[ -n "${CLAUDE_PROJECT_DIR:-}" ]]; then
  if ! "$_py" "${PLUGIN_ROOT}/hooks/lib/protocol_materialize.py" \
      --project "${CLAUDE_PROJECT_DIR}" \
      --plugin-root "${PLUGIN_ROOT}" \
      --cli "$cli" \
      --host claude; then
    echo "synaptory: required protocol bodies were not written to .synaptory/.protocols/" >&2
    exit 1
  fi
fi

SYNAPTORY_HOOK_LIB="${PLUGIN_ROOT}/hooks/lib" "$_py" -c "
import sys, os
sys.path.insert(0, os.environ['SYNAPTORY_HOOK_LIB'])
from hook_io import emit
emit('SessionStart', reload_skills=True)
" 2>/dev/null || printf '{"reloadSkills":true}\n'
